CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,name text NOT NULL,platform_admin boolean NOT NULL DEFAULT false,disabled boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE NOT NULL CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','archived')),color text NOT NULL DEFAULT '#b85b30',contact text NOT NULL DEFAULT '',timezone text NOT NULL DEFAULT 'Africa/Johannesburg',welcome text NOT NULL DEFAULT 'Welcome to your workspace',logo_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(company_id uuid REFERENCES companies NOT NULL,user_id uuid REFERENCES users NOT NULL,role text NOT NULL CHECK(role IN ('owner','manager','office administrator','supervisor','staff member','read-only user')),PRIMARY KEY(company_id,user_id));
CREATE TABLE IF NOT EXISTS modules(company_id uuid REFERENCES companies NOT NULL,module_id text NOT NULL,enabled boolean NOT NULL DEFAULT true,settings jsonb NOT NULL DEFAULT '{}',allowed_roles text[] NOT NULL DEFAULT ARRAY['owner','manager','office administrator','supervisor','staff member','read-only user'],PRIMARY KEY(company_id,module_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id uuid REFERENCES users NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(email text PRIMARY KEY,attempts integer NOT NULL DEFAULT 0,last_attempt timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid REFERENCES companies NOT NULL,subject text NOT NULL,category text NOT NULL,priority text NOT NULL,status text NOT NULL DEFAULT 'Open' CHECK(status IN ('Open','In Progress','Waiting for Customer','Resolved')),assigned_to uuid REFERENCES users,created_by uuid REFERENCES users NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,company_id));
CREATE TABLE IF NOT EXISTS messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL,company_id uuid NOT NULL,author_id uuid REFERENCES users NOT NULL,body text NOT NULL,private boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(ticket_id,company_id) REFERENCES tickets(id,company_id),UNIQUE(id,company_id));
CREATE TABLE IF NOT EXISTS files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid REFERENCES companies NOT NULL,message_id uuid,name text NOT NULL,mime text NOT NULL,data bytea NOT NULL CHECK(octet_length(data)<=2097152),FOREIGN KEY(message_id,company_id) REFERENCES messages(id,company_id));
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid REFERENCES companies NOT NULL,user_id uuid REFERENCES users NOT NULL,ticket_id uuid NOT NULL,title text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(ticket_id,company_id) REFERENCES tickets(id,company_id));
CREATE TABLE IF NOT EXISTS audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid REFERENCES companies,actor_id uuid REFERENCES users NOT NULL,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS business_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid REFERENCES companies NOT NULL,module_id text NOT NULL,data jsonb NOT NULL,created_by uuid REFERENCES users NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(company_id,module_id) REFERENCES modules(company_id,module_id));
CREATE INDEX IF NOT EXISTS tickets_company_updated ON tickets(company_id,updated_at DESC);
CREATE INDEX IF NOT EXISTS messages_ticket ON messages(ticket_id,created_at);
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,read_at);
